import { asNumber, asString, useSearchParam } from '../../url/useSearchParam';
import { type Hold, covers } from '../people/people';

/** PENDING: settled by a clerk above the clerk limit, awaiting a steward's approval; handled as OPEN,
 *  except that a statement does not bind it while it is PENDING. DELETED: a deleted DRAFT, which counts
 *  nowhere and can be restored to a DRAFT on the sheet's today it was deleted. REVIEW: opened while its due was
 *  above the review threshold on its date, awaiting a steward's review to make it OPEN; it counts in no total. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED' | 'REVIEW';

/** Only OPEN, PENDING and SETTLED claims count toward claimed and the totals; a deferred claim does not. */
export const counts = (c: Claim) => (isOpen(c) && !c.deferred) || c.status === 'SETTLED';

/** Whether the claim keeps the figure (or n/a) its person's last statement bound it to: not while PENDING. */
export const isBound = (c: Claim) => c.stated && (c.statedDue !== null || c.statedNa) && c.status !== 'PENDING';

const fixed = (claim: Claim) => claim.due !== null || (isBound(claim) && claim.statedDue !== null);

/** A claim's due: the due fixed when it was settled (its late charge frozen in), else its figure — the
 *  rate figure its person's last statement bound it to (not while PENDING), else its amount at the rate in force
 *  on the claim's date of its person's grade in force on that date — plus its late charge when overdue (worked out
 *  on that figure), and at least the sheet's floor in force on the claim's date, applied last.
 *  A correction's live due has no floor and it has no late charge.
 *  grade rate in force on the claim's date, rounded as the sheet's policy date has it (none when no rate of the grade applies then),
 *  or at the figure its person's last statement bound it to, plus the late charge it has then, and at least the sheet's floor (frozen in).
 *  A clerk's settle above the clerk limit makes it PENDING instead (see {@link CheckClerkLimit}); a steward's
 *  approval settles a PENDING claim, frozen then at its live figure (a statement does not bind it while
 *  PENDING), and a rejection moves it back to OPEN, bound again by its person's last statement if that included it.
 *  The user who opened a claim, or who last edited it, may not settle or approve it, and a claim deferred on the sheet's today may not be settled.
 *  Opening a DRAFT is refused while its person already has as many OPEN or PENDING claims in its period as the period's cap.
        if (from == ClaimStatus.DRAFT && (to == ClaimStatus.OPEN || to == ClaimStatus.REVIEW)) {
            ClaimPeriods.refuseCapped(periods, store, claim);
        }
        if (!from.canBecome(to) || !store.move(claim, from, to)) {
            throw new InvalidSheetException("A " + from + " claim cannot become " + to);
        }
        // The due to freeze is worked out while the claim is still OPEN or PENDING, so it takes its late charge in.
        BigDecimal settledDue = null;
